// Runnable demo: ordering within a partition + one consumer per partition per group.
package com.bank.ordering.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class OrderingDemo {
    private static final Logger log = Logger.getLogger(OrderingDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Topic topic = new Topic("transactions", 3);

        // Rajesh: debit then balance check — MUST stay ordered (same key)
        topic.produce("SAV2001", new AccountEvent("E1", "SAV2001", "DEBIT", new BigDecimal("50000")));
        topic.produce("SAV2001", new AccountEvent("E2", "SAV2001", "BALANCE_CHECK", new BigDecimal("0")));
        topic.produce("SAV2001", new AccountEvent("E3", "SAV2001", "DEBIT", new BigDecimal("2000")));
        topic.produce("CUR3001", new AccountEvent("E4", "CUR3001", "CREDIT", new BigDecimal("8000")));

        // Main group: 2 consumers, one partition each (no partition shared)
        GroupAssignment main = new GroupAssignment("txn-main", topic, 2);
        main.showAssignment();
        main.consumeInOrder();

        // Fraud group: independent, reads ALL partitions on its own
        GroupAssignment fraud = new GroupAssignment("fraud", topic, 3);
        fraud.consumeInOrder();
    }
}

// ─── Would be in AccountEvent.java ───
class AccountEvent {
    private final String id, accountId, type;
    private final BigDecimal amount;
    AccountEvent(String id, String accountId, String type, BigDecimal amount) {
        this.id = id; this.accountId = accountId; this.type = type; this.amount = amount;
    }
    String getAccountId() { return accountId; }
    @Override public String toString() { return id + " " + accountId + " " + type + " " + amount; }
}

// ─── Would be in OrderedPartition.java ───
class OrderedPartition {
    private final int id;
    private final List<AccountEvent> log = new ArrayList<>(); // index = offset, append-only
    OrderedPartition(int id) { this.id = id; }
    void append(AccountEvent e) { log.add(e); } // next offset, never reordered
    List<AccountEvent> records() { return log; }
    int getId() { return id; }
}

// ─── Would be in Topic.java ───
class Topic {
    private static final Logger log = Logger.getLogger(Topic.class.getName());
    private final String name;
    private final List<OrderedPartition> partitions = new ArrayList<>();
    Topic(String name, int count) {
        this.name = name;
        for (int i = 0; i < count; i++) partitions.add(new OrderedPartition(i));
    }
    int count() { return partitions.size(); }
    int partitionFor(String key) { return Math.floorMod(key.hashCode(), partitions.size()); }
    void produce(String key, AccountEvent e) {
        int p = partitionFor(key);
        partitions.get(p).append(e);
        log.info(() -> "PRODUCE key=" + key + " -> partition " + p
                + " offset " + (partitions.get(p).records().size() - 1) + " [" + e + "]");
    }
    OrderedPartition partition(int id) { return partitions.get(id); }
}

// ─── Would be in GroupAssignment.java ───
class GroupAssignment {
    private static final Logger log = Logger.getLogger(GroupAssignment.class.getName());
    private final String groupId;
    private final Topic topic;
    private final int consumers;
    GroupAssignment(String groupId, Topic topic, int consumers) {
        this.groupId = groupId; this.topic = topic; this.consumers = consumers;
    }
    // Round-robin partitions to consumers: each partition to EXACTLY one consumer
    private Map<Integer, List<Integer>> assign() {
        Map<Integer, List<Integer>> map = new TreeMap<>();
        for (int c = 0; c < consumers; c++) map.put(c, new ArrayList<>());
        for (int p = 0; p < topic.count(); p++) map.get(p % consumers).add(p);
        return map;
    }
    void showAssignment() {
        assign().forEach((c, parts) ->
            log.info(() -> "[" + groupId + "] consumer " + c + " owns partitions " + parts));
    }
    void consumeInOrder() {
        assign().forEach((c, parts) -> {
            for (int p : parts) {
                for (AccountEvent e : topic.partition(p).records()) {
                    log.info(() -> "[" + groupId + "] consumer " + c
                            + " partition " + p + " read (in order) " + e);
                }
            }
        });
    }
}

